using Servicio.RetazoMarket.Business.DTOs.Descuento;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;
public class DescuentoService:IDescuentoService {private readonly IDescuentoDataService _consultas;private readonly IDescuentoAdministracionDataService _administracion;private readonly IProductoDataService _productos;public DescuentoService(IDescuentoDataService consultas,IDescuentoAdministracionDataService administracion,IProductoDataService productos)=>(_consultas,_administracion,_productos)=(consultas,administracion,productos);public async Task<DescuentoResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _consultas.ObtenerPorIdAsync(id,ct);return m is null?null:DescuentoBusinessMapper.ToResponse(m);}public async Task<IReadOnlyList<DescuentoResponse>> ObtenerTodosAsync(CancellationToken ct=default)=>(await _consultas.ObtenerTodosAsync(ct)).Select(DescuentoBusinessMapper.ToResponse).ToList();public async Task<IReadOnlyList<DescuentoResponse>> ObtenerPorProductoAsync(int id,CancellationToken ct=default)=>(await _consultas.ObtenerPorProductoAsync(id,ct)).Select(DescuentoBusinessMapper.ToResponse).ToList();public async Task<DataPagedResult<DescuentoResponse>> BuscarAsync(DescuentoFiltroRequest f,CancellationToken ct=default){var e=DescuentoValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var r=await _consultas.BuscarAsync(new DescuentoFiltroDataModel{id_producto=f.id_producto,cantidad_minima=f.cantidad_minima,porcentaje=f.porcentaje,estado=f.estado?.Trim().ToUpperInvariant(),PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(DescuentoBusinessMapper.ToResponse).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}public async Task<DescuentoResponse> CrearAsync(CrearDescuentoRequest r,CancellationToken ct=default){var e=DescuentoValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ProductoExiste(r.id_producto,ct);if(await _consultas.ExistePorProductoYCantidadMinimaAsync(r.id_producto,r.cantidad_minima,null,ct))throw new ValidationException("Ya existe un tramo con esa cantidad mínima para el producto.");try{return DescuentoBusinessMapper.ToResponse(await _administracion.CrearAsync(DescuentoBusinessMapper.ToDataModel(r),ct));}catch(InvalidOperationException ex){throw new ValidationException(ex.Message);}}public async Task<DescuentoResponse?> ActualizarAsync(ActualizarDescuentoRequest r,CancellationToken ct=default){var e=DescuentoValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ProductoExiste(r.id_producto,ct);if(await _consultas.ExistePorProductoYCantidadMinimaAsync(r.id_producto,r.cantidad_minima,r.id_descuento,ct))throw new ValidationException("Ya existe otro tramo con esa cantidad mínima para el producto.");try{var x=await _administracion.ActualizarAsync(DescuentoBusinessMapper.ToDataModel(r),ct);return x is null?null:DescuentoBusinessMapper.ToResponse(x);}catch(InvalidOperationException ex){throw new ValidationException(ex.Message);}}public Task<bool> InactivarAsync(int id,CancellationToken ct=default)=>_administracion.InactivarAsync(id,ct);public async Task<DescuentoAplicadoResponse> CalcularAplicableAsync(int producto,int cantidad,decimal subtotal,CancellationToken ct=default){if(producto<=0||cantidad<=0||subtotal<0)throw new ValidationException("Los datos para calcular el descuento no son válidos.");await ProductoExiste(producto,ct);var regla=await _consultas.ObtenerAplicableAsync(producto,cantidad,ct);var porcentaje=regla?.porcentaje??0m;var monto=decimal.Round(subtotal*porcentaje/100m,2,MidpointRounding.AwayFromZero);return new(){id_descuento=regla?.id_descuento,id_producto=producto,cantidad_comprada=cantidad,porcentaje=porcentaje,monto_descuento=monto,total_con_descuento=decimal.Round(subtotal-monto,2,MidpointRounding.AwayFromZero)};}private async Task ProductoExiste(int id,CancellationToken ct){if(await _productos.ObtenerPorIdAsync(id,ct) is null)throw new ValidationException("El producto no existe.");}}
